package com.sigtm.backend.controller;
import com.sigtm.backend.model.ContratoProveedor; import com.sigtm.backend.service.ContratoProveedorService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.ResponseEntity; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/proveedores/{supplierId}/contratos") @RequiredArgsConstructor public class ContratoProveedorController {private final ContratoProveedorService service; @GetMapping @PreAuthorize("hasAuthority('COMPRAS:VER')") public ResponseEntity<List<ContratoProveedor>> listar(@PathVariable Long supplierId){return ResponseEntity.ok(service.listar(supplierId));} @PostMapping @PreAuthorize("hasAuthority('COMPRAS:APROBAR')") public ResponseEntity<ContratoProveedor> crear(@PathVariable Long supplierId,@Valid @RequestBody ContratoProveedor c){return ResponseEntity.ok(service.crear(supplierId,c));} @PatchMapping("/{id}/desactivar") @PreAuthorize("hasAuthority('COMPRAS:APROBAR')") public ResponseEntity<ContratoProveedor> desactivar(@PathVariable Long id){return ResponseEntity.ok(service.desactivar(id));}}
